def solve(g):
    from collections import Counter
    cnt=Counter(x for r in g for x in r); bg=cnt.most_common(1)[0][0]
    hlines=[i for i,r in enumerate(g) if len(set(r))==1 and r[0]!=bg]
    vlines=[j for j in range(len(g[0])) if len({g[i][j] for i in range(len(g))})==1 and g[0][j]!=bg]
    M=[[g[h_][v_] for v_ in vlines] for h_ in hlines]
    # value that appears most at intersections = line color
    vals=Counter(v for r in M for v in r)
    linecol=vals.most_common(1)[0][0]
    anoms={v for r in M for v in r}-{linecol}
    out=[]
    for r in M:
        row=[]
        for v in r:
            row.append(0 if v==linecol else next(iter(anoms)))
        if any(x!=0 for x in row): out.append(row)
    return out

