from collections import Counter
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
def dom(line):
    c=Counter(line); return c.most_common(1)[0][0]
def f(g):
    H,W=len(g),len(g[0])
    cnt=Counter(x for r in g for x in r); bg=cnt.most_common(1)[0][0]
    hl=[i for i in range(H) if dom(g[i])!=bg]
    vl=[j for j in range(W) if dom([g[i][j] for i in range(H)])!=bg]
    def is_seg(y0,y1,x0,x1,g):
        # segment color = most common among its 4 endpoints; marked = marker not line/bg
        pts=[g[y0][x0],g[y0][x1],g[y1][x0],g[y1][x1]]
        lc=dom(g[y0]); rc=dom([g[k][x1] for k in range(H)])
        cc={p for p in pts}
        # marker color: appears at an endpoint that differs from both local line colors AND is same across this segment?
        mks={p for p in cc if p not in (bg,lc,rc)}
        return next(iter(mks)) if len(mks)==1 else None
    out=[]
    for i in range(len(hl)-1):
        row=[]
        for j in range(len(vl)-1):
            segs=(is_seg(hl[i],hl[i+1],vl[j],vl[j]),
                  is_seg(hl[i+1],hl[i+1],vl[j],vl[j+1]),
                  is_seg(hl[i],hl[i],vl[j],vl[j]),
                  is_seg(hl[i],hl[i],vl[j+1],vl[j+1]))
            mk={s for s in segs if s is not None}
            if len(mk)==1: row.append(mk.pop())
            else: row.append(bg)
        out.append(row)
    rowsm=[k for k,r in enumerate(out) if any(x!=bg for x in r)]
    cols=[j for j in range(max(len(r) for r in out)) if any(out[i][j]!=bg for i in rowsm)]
    return [[out[i][j] for j in cols] for i in rowsm]
for n in ['Demo pair 1','Demo pair 2','Demo pair 3']:
    print(n, f(G[n+' input']), G[n+' output'])
print(json.dumps(f(G['Test input'])))

